import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static long[] mx, ct;

    static long calc(int node, int l, int r, long m) {
        if (mx[node] <= m) return 0;
        if (l == r) return 1;
        int mid = (l + r) / 2;
        if (mx[2 * node] <= m) return calc(2 * node + 1, mid + 1, r, m);
        return calc(2 * node, l, mid, m) + ct[node] - ct[2 * node];
    }

    static void pull(int node, int l, int r) {
        int mid = (l + r) / 2;
        mx[node] = Math.max(mx[2 * node], mx[2 * node + 1]);
        ct[node] = ct[2 * node] + calc(2 * node + 1, mid + 1, r, mx[2 * node]);
    }

    static void build(int node, int l, int r, long[] h) {
        if (l == r) {
            mx[node] = h[l];
            ct[node] = 1;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, h);
        build(2 * node + 1, mid + 1, r, h);
        pull(node, l, r);
    }

    static void change(int node, int l, int r, int p, long v) {
        if (l == r) {
            mx[node] = v;
            return;
        }
        int mid = (l + r) / 2;
        if (p <= mid) change(2 * node, l, mid, p, v);
        else change(2 * node + 1, mid + 1, r, p, v);
        pull(node, l, r);
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] h = new long[(int) n];
        for (int i = 0; i < h.length; i++) h[i] = Long.parseLong(next());
        long[][] ups = new long[(int) q][2];
        for (int i = 0; i < ups.length; i++) {
            for (int j = 0; j < ups[i].length; j++) {
                ups[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n;
        mx = new long[4 * cn];
        ct = new long[4 * cn];
        build(1, 0, cn - 1, h);
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < q; k++) {
            change(1, 0, cn - 1, (int) ups[k][0] - 1, ups[k][1]);
            if (k > 0) out.append(" ");
            out.append(ct[1]);
        }
        System.out.println(out);
    }
}
